import{_ as t,o as e,c as i,a2 as d}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"run","description":"","frontmatter":{},"headers":[],"relativePath":"ja/cli/run.md","filePath":"ja/cli/run.md","lastUpdated":1784903584000}'),l={name:"ja/cli/run.md"};function r(o,a,n,s,h,c){return e(),i("div",null,[...a[0]||(a[0]=[d('<h1 id="run" tabindex="-1">run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;run&quot;">​</a></h1><h2 id="目的" tabindex="-1">目的 <a class="header-anchor" href="#目的" aria-label="Permalink to &quot;目的&quot;">​</a></h2><p>対話型 <strong>TUI（Terminal User Interface）</strong> API エクスプローラーを起動します。ターミナルから離れることなく API エンドポイントを検索、ブラウズ、調査、呼び出しできるフルスクリーンアプリケーションです。</p><h2 id="使用するタイミング" tabindex="-1">使用するタイミング <a class="header-anchor" href="#使用するタイミング" aria-label="Permalink to &quot;使用するタイミング&quot;">​</a></h2><ul><li>対話的に API を探索したい場合</li><li>すべての spec にわたって特定のエンドポイントを検索する必要がある場合</li><li>spec → collection → tag → endpoint の階層をブラウズしたい場合</li><li>MCP サーバーを設定する前に API 呼び出しをテストしたい場合</li></ul><h2 id="構文" tabindex="-1">構文 <a class="header-anchor" href="#構文" aria-label="Permalink to &quot;構文&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [path]</span></span></code></pre></div><h2 id="引数" tabindex="-1">引数 <a class="header-anchor" href="#引数" aria-label="Permalink to &quot;引数&quot;">​</a></h2><table tabindex="0"><thead><tr><th>引数</th><th>位置</th><th>必須</th><th>説明</th></tr></thead><tbody><tr><td><code>path</code></td><td>1</td><td>いいえ</td><td>ワークスペースディレクトリ。省略時はパス解決ルールに従います。</td></tr></tbody></table><h2 id="フラグ" tabindex="-1">フラグ <a class="header-anchor" href="#フラグ" aria-label="Permalink to &quot;フラグ&quot;">​</a></h2><p>なし。</p><h2 id="モード" tabindex="-1">モード <a class="header-anchor" href="#モード" aria-label="Permalink to &quot;モード&quot;">​</a></h2><h3 id="検索モード" tabindex="-1">検索モード <a class="header-anchor" href="#検索モード" aria-label="Permalink to &quot;検索モード&quot;">​</a></h3><p>すべての spec の全エンドポイントに対する全文検索。HTTP メソッド、タグ、パスによるフィルタリングをサポートします。</p><ul><li>クエリを入力してエンドポイント名、パス、説明を検索</li><li>メソッド（GET、POST、PUT、DELETE など）で結果をフィルタリング</li><li>1 回のキー操作でエンドポイントの詳細を表示</li></ul><h3 id="ブラウズモード" tabindex="-1">ブラウズモード <a class="header-anchor" href="#ブラウズモード" aria-label="Permalink to &quot;ブラウズモード&quot;">​</a></h3><p>spec 階層のツリー移動：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Spec → Collection → Tag → Endpoint</span></span></code></pre></div><ul><li>ツリーを下って特定のエンドポイントを見つける</li><li>エンドポイントの詳細を表示（パラメーター、リクエストボディ、レスポンス）</li><li>TUI から直接 API を呼び出す</li></ul><h2 id="ナビゲーション" tabindex="-1">ナビゲーション <a class="header-anchor" href="#ナビゲーション" aria-label="Permalink to &quot;ナビゲーション&quot;">​</a></h2><table tabindex="0"><thead><tr><th>キー</th><th>アクション</th></tr></thead><tbody><tr><td><code>↑</code> / <code>↓</code></td><td>上下に移動</td></tr><tr><td><code>Enter</code></td><td>選択または開く</td></tr><tr><td><code>Esc</code></td><td>戻る</td></tr><tr><td><code>Tab</code></td><td>検索モードとブラウズモードを切り替え</td></tr><tr><td><code>/</code></td><td>検索入力をフォーカス</td></tr><tr><td><code>q</code></td><td>終了</td></tr></tbody></table><h2 id="コマンド実行後の確認" tabindex="-1">コマンド実行後の確認 <a class="header-anchor" href="#コマンド実行後の確認" aria-label="Permalink to &quot;コマンド実行後の確認&quot;">​</a></h2><p>TUI はワークスペースからすべての spec を読み込みます。spec の読み込みに失敗した場合、インターフェースにエラーメッセージが表示されます。</p><h2 id="ニュアンス" tabindex="-1">ニュアンス <a class="header-anchor" href="#ニュアンス" aria-label="Permalink to &quot;ニュアンス&quot;">​</a></h2><ul><li><strong>自動初期化:</strong> 設定ファイルが存在しない場合、<code>run</code> は自動的に init ウィザードを実行します。</li><li><strong>フラグなし:</strong> <code>run</code> コマンドにはフラグがありません — すべての設定はワークスペースから取得されます。</li><li><strong>ターミナルサイズ:</strong> TUI は最低 80×24 文字のターミナルが必要です。非常に小さいターミナルでは正しく表示されない場合があります。</li><li><strong>依存関係:</strong> TUI は Bubbletea を使用します。SSH 経由およびほとんどのターミナルエミュレーターで動作します。</li></ul>',25)])])}const b=t(l,[["render",r]]);export{u as __pageData,b as default};
